"""Source-backed local review: real captures plus a labelled remote model."""
from pathlib import Path
import hashlib,json,shutil,markdown
R=Path(__file__).resolve().parents[1]
O=R/'doc/research/possible-bodies';E=R/'doc/space/ca-history-review-2026-09-13'
RUN=R/'ada_run/ca-history-review-2026-09-13'
def save(p,s):p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes((s.strip()+'\n').encode('utf-8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
receipt=json.loads((RUN/'run.json').read_text())
assert receipt['exit']==0 and not receipt['failures'] and receipt['sources_unchanged']
assert all(sha(R/p)==h for p,h in receipt['source_sha256'].items()),'Capture is stale'
engine_log=(RUN/'CA_GameOfLife/engine.log').read_text(encoding='utf-8',errors='replace')
assert 'SCRIPT ERROR:' not in engine_log and 'Parse Error:' not in engine_log,'Resolve runtime script errors before publishing'
result=json.loads((RUN/'CA_GameOfLife/probe_ca_history_live.json').read_text())
for name in ['entrance','lattice','controls','readout','whole-hall']:
 shutil.copy2(RUN/f'CA_GameOfLife/{name}.png',O/f'ca-history-{name}.png')
shutil.copy2(R/'tools/ca_history_model.js',O/'ca-history-model.js')
for name in ['final','technical','critical','tutorial','field_notes']:
 shutil.copy2(R/f'commons/maps/CA_GameOfLife/{name}.md',O/f'ca-history-{name}.md')
save(E/'runtime-receipt.json',json.dumps(receipt,indent=2))
save(E/'runtime-verification.json',json.dumps(result,indent=2))
body=markdown.markdown((R/'commons/maps/CA_GameOfLife/final.md').read_text(encoding='utf-8'),extensions=['fenced_code'])
css='''*{box-sizing:border-box}body{margin:0;background:#10292f;color:#f0eedf;font:17px/1.7 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:30px 26px 80px}nav{display:flex;gap:24px;flex-wrap:wrap;font-size:14px}a{color:#f0cba6}h1{font:clamp(44px,7vw,75px)/1.05 Georgia,serif;max-width:850px;margin:26px 0}h2{font:32px/1.2 Georgia,serif}.lead{font-size:22px;max-width:820px}.eyebrow{letter-spacing:.14em;text-transform:uppercase;font-size:12px;color:#86d9bd;margin-top:45px}.status{background:#203e43;border-left:3px solid #dca6d5;padding:15px 20px;font-size:14px}section{margin:48px 0}figure{margin:24px 0}img{display:block;width:100%;border-radius:9px}figcaption{font-size:14px;color:#bcd1cb;margin-top:9px}.gallery{display:grid;grid-template-columns:1fr 1fr;gap:22px}.controls{display:flex;flex-wrap:wrap;gap:9px}button{padding:11px 17px;border:1px solid #94b4ae;border-radius:5px;background:#294950;color:#f5edda;font:15px system-ui;cursor:pointer}button:hover,button[aria-pressed=true]{background:#eed1ad;color:#183137}.models{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.models article{background:#18343b;border-radius:9px;padding:13px}.models h3{font-size:17px;margin:4px 0}.models svg{width:100%;display:block}.small{font-size:14px;color:#bdd3cd}.reading{max-width:780px;margin:auto}.reading h1{font-size:43px}.reading p{margin:1.4em 0}.reading pre{overflow:auto;background:#19373c;padding:18px;font-size:14px}summary{font-size:23px;cursor:pointer}details{border-top:1px solid #4c6e71;padding-top:20px}table{border-collapse:collapse;width:100%;font-size:15px}th,td{padding:11px;border-bottom:1px solid #456169;text-align:left;vertical-align:top}code{overflow-wrap:anywhere}@media(max-width:720px){main{padding:22px 17px}.gallery,.models{grid-template-columns:1fr}.lead{font-size:19px}}'''
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>A history you can inhabit · Ada Research</title><style>__CSS__</style></head><body><main><nav><a href="learning-ladder.html">← Pedagogical ladder</a><a href="/necklace/thread?map=CA_GameOfLife&role=primary">The room’s primary</a><a href="/museum-progress?sequence=cellularautomata&room=CA_GameOfLife">Museum progress</a></nav><div class="eyebrow">Cellular automata / CA_GameOfLife</div><h1>A history you can inhabit</h1><p class="lead">A gap lets the eye through. Underfoot, it asks for another route. One recorded history becomes a desk, stepping tiles and a lattice along the museum.</p><p class="status">Implemented in Godot · __CHECKS__ desktop checks passed. Real museum captures below. All five artifacts remain; the original lab keeps its full size beside an added aisle. Headset review and the retained secondary encounters remain further work.</p><figure id="in-museum"><img src="ca-history-entrance.png" alt="Actual Godot museum: a mint and lilac cellular history lies over a shallow basin beside its framed lattice screen"><figcaption>Actual Godot capture, at eye height. The screenshot shows the full 24-row record; arrival is held at 12 rows. The visitor can follow the ordinary museum floor around it.</figcaption></figure><section><h2>One record, three uses</h2><p>The desk and the spatial objects read the same stored generations. STEP adds one row; REPLAY returns to the beginning. The gold witness follows a chosen generation across all three mappings.</p><div class="gallery"><figure><img src="ca-history-controls.png" alt="A tilted history desk with six buttons and an upright cased readout"><figcaption>The controls alter the beginning or the local experiment clock. They do not stop the museum clock.</figcaption></figure><figure><img src="ca-history-lattice.png" alt="The same CA history used as coloured infill in a bronze screen above a matching tile pattern"><figcaption>The screen wears the record. Coloured infill is visual; the bronze frame stands independently. Occupied deck tiles have collision.</figcaption></figure></div></section><section><h2>Try the relationship remotely</h2><p class="small">An explanatory browser model of the same fifteen-site, periodic Rule 30. It shows shared data and mappings; it does not simulate Godot collision. Here SEED alternates SINGLE and PAIR. Godot also offers a locally seeded random beginning.</p><div class="controls"><button id="step">STEP</button><button id="run" aria-pressed="false">RUN</button><button id="replay">REPLAY</button><button id="seed">SEED</button><button id="flip">FLIP X9</button><button id="row">ROW</button></div><p id="status" role="status"></p><p class="small"><span id="count"></span> occupied recorded cells, used in each mapping. Gold marks the selected generation.</p><div class="models"><article><h3>1 / A flat record</h3><div id="desk"></div></article><article><h3>2 / Tiles that could carry</h3><div id="tiles"></div></article><article><h3>3 / A screen wears the past</h3><div id="screen"></div></article></div></section><section><h2>Where this can go in the museum</h2><table><thead><tr><th>Encounter</th><th>Application</th><th>What must remain visible</th></tr></thead><tbody><tr><td>Built here</td><td>Recorded CA as lattice, cladding and support tiles.</td><td>The same history; different mappings and collision.</td></tr><tr><td>Next: the Life dish</td><td>A travelling pattern could trigger neighbouring lamps or objects as it reaches their addresses.</td><td>Fixed addresses, changing occupancy; the event rule connecting them.</td></tr><tr><td>Expanding Space</td><td>Proximity changes the state of a surface and whether it supports the visitor.</td><td>The input is distance, not measured weight. Appearance and support have thresholds.</td></tr><tr><td>Soft Rules, after the live study</td><td>A coupled field could dress a wall, object or garment.</td><td>Actual field evolution, mapping and exchange. A smooth image alone is not that mechanism.</td></tr></tbody></table><p>The first application is installed. The others are directions for their halls. A beautiful surface becomes a useful question when we can change its conditions and discover what it permits.</p></section><section><details><summary>Read the revised book passage</summary><div class="reading">__BODY__</div></details></section><section><details><summary>See the whole hall and verification</summary><figure><img src="ca-history-whole-hall.png" alt="Actual overhead Godot capture of the new history bay and retained rear collection"><figcaption>The history bay comes before the retained gallery. An added eastern aisle lets the old lab remain full size.</figcaption></figure><figure><img src="ca-history-readout.png" alt="Close-up of the housed Rule 30 readout"><figcaption>Readable state, generation range, selected row and beginning.</figcaption></figure><p>__CHECKS__ real-engine checks cover the inherited rule, periodic edge, replay, one-bit intervention, record limit, shared mappings, physical support, six real pointer controls and a walked portion of the museum margin. This is desktop evidence; it does not certify headset comfort or every retained secondary interaction.</p><p><a href="ca-history-technical.md">Technical account</a> · <a href="ca-history-critical.md">Critical text</a> · <a href="ca-history-field_notes.md">Field notes</a> · <a href="ca-history-verification.json">Verification</a></p></details></section><footer class="small"><a href="ca-history-final.md">Book source</a> · Next: a pattern travels while its cell addresses remain in place.</footer></main><script src="ca-history-model.js"></script></body></html>'''
save(O/'ca-history-bridge.html',html.replace('__CSS__',css).replace('__BODY__',body).replace('__CHECKS__',str(receipt['checks'])))
verification={'checks':receipt['checks'],'failures':receipt['failures'],'headset_verified':False,'desktop_pointer':'synthetic mouse events through the real project pointer, inside the actual museum','support_rays':result['measurements']['support_rays'],'margin_walk':result['measurements']['margin_walk'],'last_step_ms':result['measurements']['last_step_ms'],'scope':'One desktop measurement, coexisting editor and game; not a headset frame-budget result','source_sha256':receipt['source_sha256']}
save(O/'ca-history-verification.json',json.dumps(verification,indent=2))
manifest=[p.relative_to(R/'doc/research').as_posix() for p in O.glob('ca-history-*') if p.suffix in ['.html','.png','.js','.md','.json']]
save(E/'publish-targets.json',json.dumps(sorted(manifest),indent=2))
save(E/'publish-hashes.json',json.dumps({p:sha(R/'doc/research'/p) for p in manifest},indent=2))
print('Built current review page, real captures, five texts and remote model; source hashes match the runtime receipt.')
